    public static bool IsTypeTable(string table) => Types.Any(t => t.Table.Equals(table, StringComparison.OrdinalIgnoreCase));

    public static string? TypeOf(string table) => Types.FirstOrDefault(t => t.Table.Equals(table, StringComparison.OrdinalIgnoreCase)).Type;

    private static readonly string[] Dofs = ["U1", "U2", "U3", "R1", "R2", "R3"];

    private static double Num(string? v) => double.TryParse(v, NumberStyles.Float, CultureInfo.InvariantCulture, out var d) && double.IsFinite(d) ? Math.Max(0, d) : 0;

    /// <summary>A fixed direction, for the Engine's own analysis: stiff enough to hold it, as ETABS's Fixed does.</summary>
    public const double FixedStiffness = 1e12;

    /// <summary>After a link's rows change: the Engine's link of that name follows its type and each direction's effective
    /// stiffness and damping. No rows: nothing changes (Delete Property is define_link's delete).</summary>
    public static void Sync(StructuralModel m, string name)
    {
        var tables = m.DefinitionTables;
        List<Dictionary<string, string>> Rows(string t) => tables?.GetValueOrDefault(t)?.Where(r => r.GetValueOrDefault("Name") == name).ToList() ?? [];
        var own = Types.Select(t => (t.Type, t.Table, Rows: Rows(t.Table))).FirstOrDefault(t => t.Rows.Count > 0);
        if (own.Rows is null) return; // deleting a link is define_link's (it takes every row and the Engine's link)
        var dofs = new Dictionary<string, (double, double)>();
        if (own.Type == "Linear")
        {
            var r = own.Rows[0];
            for (var i = 0; i < 6; i++)
            {
                var status = r.GetValueOrDefault(Dofs[i] + "Status") ?? "";
                if (status.Length == 0 || status.Equals("Inactive", StringComparison.OrdinalIgnoreCase)) continue;
                dofs[Dofs[i]] = status.Equals("Fixed", StringComparison.OrdinalIgnoreCase) ? (FixedStiffness, 0) : (Num(r.GetValueOrDefault($"StiffU{i + 1}")), Num(r.GetValueOrDefault($"DampU{i + 1}")));
            }
        }
        else
            foreach (var r in own.Rows)
            {
                var dof = (r.GetValueOrDefault("Direction") ?? "").ToUpperInvariant();
                if (!Dofs.Contains(dof) || dofs.ContainsKey(dof)) continue;
                var rot = dof[0] == 'R';
                dofs[dof] = StructureExtras.Yes(r, "Fixed", false) ? (FixedStiffness, 0) : (Num(r.GetValueOrDefault(rot ? "RotKE" : "TransKE")), Num(r.GetValueOrDefault(rot ? "RotCE" : "TransCE")));
            }
        if (dofs.Count == 0) dofs["U1"] = (0, 0);
        PropertyDefs.SetLink(m, name, PropertyDefs.EngineLinkType(own.Type), dofs);
        // The link is in one type's table only (its type changed: the old type's rows go).
        foreach (var (_, t) in Types.Where(t => t.Table != own.Table))
            if (Rows(t).Count > 0) DefineTables.Set(m, t, name, []);
    }

    /// <summary>Takes a link out of every ETABS link table.</summary>
    public static void Remove(StructuralModel m, string name)
    {
        foreach (var t in Tables.Keys)
            if (m.DefinitionTables?.GetValueOrDefault(t)?.Exists(r => r.GetValueOrDefault("Name") == name) == true) DefineTables.Set(m, t, name, []);
    }
}
